from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
path='/root/data/workbook.xlsx'
wb=load_workbook(path, data_only=False)
print('Sheets:', wb.sheetnames)
ws=wb['Task']
wd=wb['Data']
print('\nTask column D rows 12-17:')
for r in range(12,18): print(r, repr(ws[f'D{r}'].value))
print('\nTask column D rows 19-24:')
for r in range(19,25): print(r, repr(ws[f'D{r}'].value))
print('\nTask column D rows 26-31:')
for r in range(26,32): print(r, repr(ws[f'D{r}'].value))
print('\nTask row 10 H-L:')
for c in range(8,13): print(get_column_letter(c)+'10', repr(ws.cell(10,c).value))
print('\nTask rows 35-50 (A-L values/formulas):')
for r in range(35,51):
    vals=[ws.cell(r,c).value for c in range(1,13)]
    print(r, vals)
print('\nData rows 21-38 (A-Z):')
for r in range(21,39):
    vals=[wd.cell(r,c).value for c in range(1,27)]
    print(r, vals)
# Determine nonempty bounds in rows 21-38 cols A:ZZ
non=[]
for r in range(21,39):
    for c in range(1,wd.max_column+1):
        if wd.cell(r,c).value is not None:
            non.append((r,c,wd.cell(r,c).value))
print('\nData max_row/max_col:', wd.max_row, wd.max_column, get_column_letter(wd.max_column))
if non:
    minr=min(x[0] for x in non); maxr=max(x[0] for x in non); minc=min(x[1] for x in non); maxc=max(x[1] for x in non)
    print('Nonempty bounds rows 21-38:', minr, maxr, get_column_letter(minc), get_column_letter(maxc))
    print('Header nonempty row 21:')
    for c in range(minc,maxc+1): print(get_column_letter(c), repr(wd.cell(21,c).value))
    print('Series codes col A rows 22-38:')
    for r in range(22,39): print(r, repr(wd.cell(r,1).value))
